import json, re, sys
from collections import Counter, defaultdict
from pathlib import Path
root, names = Path(sys.argv[1]), Path(sys.argv[2]).read_text().split()
MEM = re.compile(r"\.claude/projects/[^\s\"']*/memory/")
summary = defaultdict(Counter)
tool_ids = {}
for n in names:
    for line in (root / n / "transcript.jsonl").read_text(errors="replace").splitlines():
        r = json.loads(line); t = r.get("type"); s = json.dumps(r)
        if not MEM.search(s) and "Contents of" not in s: continue
        msg = r.get("message") or {}
        cont = msg.get("content") if isinstance(msg.get("content"), list) else []
        kinds = set()
        for part in cont:
            if part.get("type") == "tool_use":
                inp = json.dumps(part.get("input", {}))
                if MEM.search(inp):
                    kinds.add(f"tool_use:{part.get('name')}"); tool_ids[part.get("id")] = part.get("name")
            if part.get("type") == "tool_result" and part.get("tool_use_id") in tool_ids:
                kinds.add(f"tool_result:{tool_ids[part['tool_use_id']]}")
        if re.search(r"Contents of [^\"]*MEMORY\.md", s): kinds.add(f"memory-index-block in {t}")
        if not kinds: kinds.add(f"mention only in {t}")
        for k in kinds: summary[n][k] += 1
agg = Counter()
for n, c in summary.items():
    for k, v in c.items(): agg[k] += v
print("across candidate folders:"); [print("  ", v, k) for k, v in agg.most_common()]
calls = {n: sum(v for k, v in c.items() if k.startswith("tool_use")) for n, c in summary.items()}
print("folders with memory tool calls:", sum(1 for v in calls.values() if v), "of", len(names))
print("folders with an embedded memory index:", sum(1 for c in summary.values() if any(k.startswith("memory-index") for k in c)))
EOF

