import json, re, sys
from collections import Counter
from pathlib import Path
root, names = Path(sys.argv[1]), Path(sys.argv[2]).read_text().split()
MEM = re.compile(r"\.claude/projects/[^\s\"']*/memory/")
att, usr, fh, bash = Counter(), Counter(), Counter(), Counter()
for n in names:
    for line in (root / n / "transcript.jsonl").read_text(errors="replace").splitlines():
        r = json.loads(line); s = json.dumps(r)
        if not MEM.search(s): continue
        t = r.get("type")
        if t == "attachment":
            a = r.get("attachment") or {}
            att[(a.get("type"), "has 'content'" if "content" in json.dumps(a) else "", len(s) // 1000)] += 1
        elif t == "user":
            for p in (r.get("message") or {}).get("content") or []:
                if isinstance(p, dict) and MEM.search(json.dumps(p)): usr[p.get("type")] += 1
        elif t in ("file-history-delta", "file-history-snapshot"):
            fh[(t, "memory path in trackingPath/backup" if MEM.search(json.dumps({k: r.get(k) for k in ("trackingPath", "backup", "snapshot")})) else "other", len(s) // 1000)] += 1
        elif t == "assistant":
            for p in (r.get("message") or {}).get("content") or []:
                if p.get("type") == "tool_use" and p.get("name") == "Bash" and MEM.search(json.dumps(p.get("input"))):
                    cmd = p["input"].get("command", "")
                    verb = re.findall(r"\b(python3|grep|cat|sed|ls|wc|head|tail|cp|mv|rm|echo|awk|find|cd)\b", cmd)
                    bash[" ".join(dict.fromkeys(verb))[:40]] += 1
print("attachments (type, content?, KB):", att.most_common(12))
print("user parts:", dict(usr))
print("file-history records:", fh.most_common(8))
print("memory Bash command verbs:", bash.most_common(12))
EOF

