import json, re, sys
from collections import Counter
from pathlib import Path
root, names = Path(sys.argv[1]), Path(sys.argv[2]).read_text().split()
CATS = {"private-plan": re.compile(r"implementation-plan"), "git-exclude": re.compile(r"\.git/info/exclude"),
        "app-list": re.compile(r"\b(ps (aux|-e|-A)|lsof\b|osascript|ls /Applications|mdfind|system_profiler|launchctl list|pmset -g assertions|brew list|top -l)"),
        "docker-names": re.compile(r"\{\{\.Names\}\}|com\.docker\.compose\.project=(?!etf-risk)"),
        "memory-frontmatter": re.compile(r"\nmetadata:\n\s+(node_)?type: |\nmetadata:\\n")}
INDEX = re.compile(r"Contents of [^\n]*MEMORY\.md")
where = {k: Counter() for k in CATS}
examples = {k: [] for k in CATS}
for n in names:
    recs = [json.loads(l) for l in (root / n / "transcript.jsonl").read_text(errors="replace").splitlines()]
    tools = {}
    for r in recs:
        msg = r.get("message") or {}
        parts = msg.get("content") if isinstance(msg.get("content"), list) else [{"type": "record", "text": json.dumps(r)}]
        for p in parts:
            if not isinstance(p, dict): continue
            if p.get("type") == "tool_use": tools[p.get("id")] = (p.get("name"), json.dumps(p.get("input"))[:0])
            s = json.dumps(p)
            for k, pat in CATS.items():
                for m in pat.finditer(s):
                    ctx = s[max(0, m.start() - 70):m.end() + 50]
                    if INDEX.search(s) and "memory" in ctx.lower(): place = "inside memory index/rules text"
                    elif "/memory/" in s: place = "inside a memory-file operation"
                    else:
                        place = f"{r.get('type')}:{p.get('type')}" + (f":{p.get('name')}" if p.get("type") == "tool_use" else "") + (f":result-of-{tools.get(p.get('tool_use_id'), ('?',))[0]}" if p.get("type") == "tool_result" else "")
                    where[k][place] += 1
                    if not place.startswith("inside") and len(examples[k]) < 4:
                        examples[k].append(f"{n}: {place}: …{re.sub(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+', '<email>', ctx)!r}…")
for k in CATS:
    print(f"== {k}: {dict(where[k])}")
    for e in examples[k]: print("   ", e[:300])
md_hit = []
for n in names:
    for i, line in enumerate((root / n / "transcript.md").read_text(errors="replace").splitlines(), 1):
        if re.search(r"\"type\":\s*\"thinking\",\s*\"thinking\":\s*\"(?!\[REDACTED)", line): md_hit.append(f"{n}/transcript.md:{i} (len {len(line)})")
print("== md thinking-pattern hits:", md_hit)
EOF

