"""Remove Claude Code memory content from redacted AI logs, consistently in both formats.

For each folder: sanitize transcript.jsonl record by record, then re-render transcript.md from it
with the committed hook's render_markdown, adding "memory ×N" to the header's redaction summary.
Removed, each replaced by [REDACTED:memory]:
- tool calls on memory files (path under .claude/projects/<project>/memory/): Write content,
  Edit old/new strings, MultiEdit edits, Bash commands; their tool results and the structured
  toolUseResult of the same calls;
- the memory index block (the lines after "Contents of …/memory/MEMORY.md …:") in any string;
- attachments about a memory file (their text fields; paths kept).
usage: python -I sanitize_memory.py <hooks dir> <ai-usage dir> <folder names file> [--check-render | --write]
"""
import json
import re
import sys
from collections import Counter
from datetime import datetime
from pathlib import Path

hooks, root, names = Path(sys.argv[1]), Path(sys.argv[2]), Path(sys.argv[3]).read_text().split()
sys.path.insert(0, str(hooks))
from save_transcript import render_markdown  # noqa: E402  the committed hook's renderer

MARK = "[REDACTED:memory]"
MEM = re.compile(r"\.claude/projects/[^\s\"'`]*?/memory/")
INDEX = re.compile(r"(Contents of [^\n]*?/memory/MEMORY\.md[^\n]*\n\n)((?:- [^\n]*(?:\n|$))+)")
INDEX_ESC = re.compile(r"(Contents of (?:(?!\\n)[^\n])*?/memory/MEMORY\.md(?:(?!\\n)[^\n])*\\n\\n)((?:- (?:(?!\\n)[^\n])*(?:\\n|$))+)")
KEEP_KEYS = {"type", "filename", "path", "filePath", "file_path", "displayPath", "tool_use_id", "uuid", "id"}
HEADER = re.compile(r"^# Claude Code message (\d+)\n\nSession: `([^`]+)` · prompt sent (\d{4}-\d{2}-\d{2} \d{2}:\d{2}) \(local time\)")
SUMMARY = re.compile(r"Redactions \(markers like `\[REDACTED:email\]`; home directory shown as `~`\): (.*?)\. Rules:")


def memory_tool_ids(records):
    ids = set()
    def walk(o):
        if isinstance(o, dict):
            if o.get("type") == "tool_use" and MEM.search(json.dumps(o.get("input", {}))):
                ids.add(o.get("id"))
            for v in o.values():
                walk(v)
        elif isinstance(o, list):
            for v in o:
                walk(v)
    for r in records:
        walk(r)
    return ids


def sanitize(obj, ids, count):
    if isinstance(obj, str):
        new = INDEX.sub(lambda m: m.group(1) + MARK + "\n", obj)
        new = INDEX_ESC.sub(lambda m: m.group(1) + MARK + "\\n", new)
        if new != obj:
            count["memory"] += 1
        return new
    if isinstance(obj, list):
        return [sanitize(v, ids, count) for v in obj]
    if not isinstance(obj, dict):
        return obj
    kind = obj.get("type")
    if kind == "tool_use" and obj.get("id") in ids:
        inp = dict(obj.get("input") or {})
        for key in ("content", "old_string", "new_string", "command", "edits", "new_source"):
            if key in inp:
                inp[key] = MARK
        count["memory"] += 1
        return {**obj, "input": inp}
    if kind == "tool_result" and obj.get("tool_use_id") in ids:
        count["memory"] += 1
        return {**obj, "content": MARK}
    out = {}
    for k, v in obj.items():
        if k == "toolUseResult" and any(isinstance(p, dict) and p.get("tool_use_id") in ids
                                        for p in ((obj.get("message") or {}).get("content") or [])
                                        if isinstance((obj.get("message") or {}).get("content"), list)):
            out[k] = MARK
            count["memory"] += 1
        elif k == "attachment" and isinstance(v, dict) and MEM.search(json.dumps(v)) and v.get("type") not in (
                "prompt_snapshot", "instructions"):
            out[k] = {ak: (av if ak in KEEP_KEYS or not isinstance(av, (str, list, dict)) else MARK) for ak, av in v.items()}
            count["memory"] += 1
        else:
            out[k] = sanitize(v, ids, count)
    return out


def render(folder: Path, jsonl: str, extra: Counter) -> str:
    md = (folder / "transcript.md").read_text(encoding="utf-8")
    number, session, sent = HEADER.match(md).groups()
    summary = SUMMARY.search(md).group(1)
    counts = Counter() if summary == "none" else Counter({k: int(v) for k, v in (x.rsplit(" ×", 1) for x in summary.split(", "))})
    counts.update(extra)
    return render_markdown(jsonl, session, int(number), datetime.strptime(sent, "%Y-%m-%d %H:%M"), counts)


mode = sys.argv[4] if len(sys.argv) > 4 else "--check-render"
mismatch, changed, total = [], {}, Counter()
for name in names:
    folder = root / name
    jsonl = (folder / "transcript.jsonl").read_text(encoding="utf-8")
    if mode == "--check-render":
        if render(folder, jsonl, Counter()) != (folder / "transcript.md").read_text(encoding="utf-8"):
            mismatch.append(name)
        continue
    records = [json.loads(line) for line in jsonl.splitlines() if line.strip()]
    ids = memory_tool_ids(records)
    count = Counter()
    new_jsonl = "\n".join(json.dumps(sanitize(r, ids, count), ensure_ascii=False) for r in records) + "\n"
    if count:
        changed[name] = count["memory"]
        total.update(count)
        if mode == "--write":
            (folder / "transcript.jsonl").write_text(new_jsonl, encoding="utf-8")
            (folder / "transcript.md").write_text(render(folder, new_jsonl, count), encoding="utf-8")
if mode == "--check-render":
    print(f"renderer reproduces the existing transcript.md exactly in {len(names) - len(mismatch)} of {len(names)} folders;"
          f" mismatches: {mismatch}")
else:
    print(f"{mode}: {len(changed)} folders with memory content, {total['memory']} items replaced")
    print(" ".join(f"{k.split('_')[-1]}:{v}" for k, v in sorted(changed.items())))

