import json
import re
import sys
from collections import Counter
from datetime import datetime
from pathlib import Path

hooks, root, names = Path(sys.argv[1]), Path(sys.argv[2]), Path(sys.argv[3]).read_text().split()
sys.path.insert(0, str(hooks))
from save_transcript import render_markdown  # noqa: E402  the committed hook's renderer

MARK = "[REDACTED:memory]"
MEM = re.compile(r"\.claude/projects/[^\s\"'`]*?/memory(?:/|\b)")
RESULT = re.compile(r"(Result of calling the Read tool:\s*)(.*?)(?=\n*</system-reminder>|\n\nCalled the |\Z)", re.S)
INDEX = re.compile(r"(Contents of [^\n]*?/memory/MEMORY\.md[^\n]*\n\n)((?:- [^\n]*(?:\n|$))+)")
INDEX_ESC = re.compile(r"(Contents of (?:(?!\\n)[^\n])*?/memory/MEMORY\.md(?:(?!\\n)[^\n])*\\n\\n)((?:- (?:(?!\\n)[^\n])*(?:\\n|$))+)")
TOPIC = re.compile(r"(Contents of [^\n]*?/memory/(?!MEMORY\.md)[^\n]*?:\n\n)(.*?)(?=\n\nContents of |\n*</system-reminder>|\n\n# |\Z)", re.S)
TOPIC_ESC = re.compile(r"(Contents of (?:(?!\\n).)*?/memory/(?!MEMORY\.md)(?:(?!\\n).)*?:\\n\\n)(.*?)(?=\\n\\nContents of |(?:\\n)*</system-reminder>|\\n\\n# |\Z)", re.S)
READ = re.compile(r"(Called the Read tool with the following input: \{[^}]*?/memory/[^}]*\}\s*Result of calling the Read tool:\s*)(.*?)(?=\n\nCalled the |\n*</system-reminder>|\n\nNote: |\Z)", re.S)
KEEP_KEYS = {"type", "filename", "path", "filePath", "file_path", "displayPath", "tool_use_id", "uuid", "id"}
HEADER = re.compile(r"^# Claude Code message (\d+)\n\nSession: `([^`]+)` · prompt sent (\d{4}-\d{2}-\d{2} \d{2}:\d{2}) \(local time\)")
SUMMARY = re.compile(r"Redactions \(markers like `\[REDACTED:email\]`; home directory shown as `~`\): (.*?)\. Rules:")


def memory_tool_ids(records):
    ids = set()
    def walk(o):
        if isinstance(o, dict):
            if o.get("type") == "tool_use" and MEM.search(json.dumps(o.get("input", {}))):
                ids.add(o.get("id"))
            for v in o.values():
                walk(v)
        elif isinstance(o, list):
            for v in o:
                walk(v)
    for r in records:
        walk(r)
    return ids


def sanitize(obj, ids, count):
    if isinstance(obj, str):
        new = INDEX.sub(lambda m: m.group(1) + MARK + "\n", obj)
        new = INDEX_ESC.sub(lambda m: m.group(1) + MARK + "\\n", new)
        new = TOPIC.sub(lambda m: m.group(1) + MARK, new)
        new = TOPIC_ESC.sub(lambda m: m.group(1) + MARK, new)
        new = READ.sub(lambda m: m.group(1) + MARK, new)
        if "node_type: memory" in new:
            new = RESULT.sub(lambda m: m.group(1) + MARK if "node_type: memory" in m.group(2) else m.group(0), new)
        if new != obj:
            count["memory"] += 1
        return new
    if isinstance(obj, list):
        return [sanitize(v, ids, count) for v in obj]
    if not isinstance(obj, dict):
        return obj
    kind = obj.get("type")
    if kind == "tool_use" and obj.get("id") in ids:
        inp = dict(obj.get("input") or {})
        for key in ("content", "old_string", "new_string", "command", "edits", "new_source"):
            if key in inp:
                inp[key] = MARK
        count["memory"] += 1
        return {**obj, "input": inp}
    if kind == "tool_result" and obj.get("tool_use_id") in ids:
        count["memory"] += 1
        return {**obj, "content": MARK}
    out = {}
    for k, v in obj.items():
        if k == "wireToolInputs" and isinstance(v, dict):
            out[k] = {tid: ({ik: (MARK if ik in ("content", "old_string", "new_string", "command", "edits", "new_source") else iv)
                             for ik, iv in inp.items()} if tid in ids and isinstance(inp, dict) else sanitize(inp, ids, count))
                      for tid, inp in v.items()}
            if any(tid in ids for tid in v):
                count["memory"] += sum(1 for tid in v if tid in ids)
            continue
        if k == "files" and isinstance(v, list) and all(isinstance(f, dict) for f in v):
            new_files = []
            for f in v:
                if MEM.search(json.dumps({fk: fv for fk, fv in f.items() if fk in KEEP_KEYS})):
                    new_files.append({fk: (fv if fk in KEEP_KEYS else MARK) for fk, fv in f.items()})
                    count["memory"] += 1
                else:
                    new_files.append(sanitize(f, ids, count))
            out[k] = new_files
            continue
        if k == "toolUseResult" and any(isinstance(p, dict) and p.get("tool_use_id") in ids
                                        for p in ((obj.get("message") or {}).get("content") or [])
                                        if isinstance((obj.get("message") or {}).get("content"), list)):
            out[k] = MARK
            count["memory"] += 1
        elif k == "attachment" and isinstance(v, dict) and MEM.search(json.dumps(v)) and v.get("type") not in (
                "prompt_snapshot", "instructions"):
            out[k] = {ak: (av if ak in KEEP_KEYS or not isinstance(av, (str, list, dict)) else MARK) for ak, av in v.items()}
            count["memory"] += 1
        elif k == "rendered" and isinstance(obj.get("attachment"), dict) and MEM.search(json.dumps(obj["attachment"])) \
                and obj["attachment"].get("type") not in ("prompt_snapshot", "instructions"):
            out[k] = MARK
            count["memory"] += 1
        else:
            out[k] = sanitize(v, ids, count)
    return out


def render(folder: Path, jsonl: str, extra: Counter) -> str:
    md = open(folder / "transcript.md", encoding="utf-8", newline="").read()
    number, session, sent = HEADER.match(md).groups()
    summary = SUMMARY.search(md).group(1)
    counts = Counter() if summary == "none" else Counter({k: int(v) for k, v in (x.rsplit(" ×", 1) for x in summary.split(", "))})
    counts.update(extra)
    return render_markdown(jsonl, session, int(number), datetime.strptime(sent, "%Y-%m-%d %H:%M"), counts)


mode = sys.argv[4] if len(sys.argv) > 4 else "--check-render"
mismatch, changed, total = [], {}, Counter()
for name in names:
    folder = root / name
